class JSVal:
    __slots__ = ("v",)

    def __init__(self, v=UNDEFINED):
        if isinstance(v, JSVal):
            v = v.v
        self.v = v

    @staticmethod
    def wrap(v):
        if isinstance(v, JSVal):
            return v
        if v is UNDEFINED:
            return JSVal(UNDEFINED)
        if isinstance(v, dict):
            return JSVal(OrderedDict((str(k), JSVal.wrap(val)) for k, val in v.items()))
        if isinstance(v, list) or isinstance(v, tuple):
            return JSVal([JSVal.wrap(x) for x in v])
        return JSVal(v)

    def is_undefined(self):
        return self.v is UNDEFINED

    def is_null(self):
        return self.v is None

    def unwrap(self, nested=True):
        if self.v is UNDEFINED:
            return None if nested else UNDEFINED
        if isinstance(self.v, OrderedDict) or isinstance(self.v, dict):
            return OrderedDict((k, JSVal.wrap(v).unwrap(True)) for k, v in self.v.items())
        if isinstance(self.v, list):
            return [JSVal.wrap(x).unwrap(True) for x in self.v]
        return self.v

