        return JSVal(sep.join("" if JSVal.wrap(x).is_undefined() or JSVal.wrap(x).is_null() else js_to_string(x) for x in self.v))

    def _arr_includes(self, item):
        item = JSVal.wrap(item)
        return JSVal(any(js_equal(JSVal.wrap(v), item) for v in self.v))

    def _arr_index_of(self, item):
        item = JSVal.wrap(item)
        for i, v in enumerate(self.v):
            if js_equal(JSVal.wrap(v), item):
                return JSVal(i)
        return JSVal(-1)

    def _arr_sort(self, fn=UNDEFINED):
        vals = list(self.v)
