#!/usr/bin/env python3
import sys, os, json, math, re, glob, time, random
from collections import OrderedDict

VERSION = "39.2.0"

HELP_TEXT = """
  fx 39.2.0
    Terminal JSON viewer

  Usage
    fx data.json
    fx data.json .field
    curl ... | fx

  Flags
    -h, --help            print help
    -v, --version         print version
    --themes              print themes
    --comp <shell>        print completion script
    -r, --raw             treat input as a raw string
    -s, --slurp           read all inputs into an array
    --yaml                parse input as YAML
    --toml                parse input as TOML
    --strict              strict mode
    --no-inline           disable inlining in output
    --game-of-life        play the game of life

  More info
    https://fx.wtf

  Author
    Anton Medvedev <anton@medv.io>
"""

ZSH_COMP = """#compdef fx

_fx() {
    local -a reply
    reply=("${(@f)$(COMP_ZSH="${LBUFFER}" fx)}")
    if (( ${#reply} )); then
        local -a insert_files display_files insert_other display_other
        local line display rest value typ

        for line in "${reply[@]}"; do
            display="${line%%$'\t'*}"
            rest="${line#*$'\t'}"
            value="${rest%%$'\t'*}"
            typ="${rest#*$'\t'}"

            if [[ "$typ" == "file" ]]; then
                display_files+=("$display")
                insert_files+=("$value")
            else
                display_other+=("$display")
                insert_other+=("$value")
            fi
        done

        if (( ${#insert_files} )); then
            compadd -f -d display_files -a insert_files
        fi
        if (( ${#insert_other} )); then
            compadd -S '' -d display_other -a insert_other
        fi
    fi
}

if [ "$funcstack[1]" = "_fx" ]; then
    _fx "$@"
else
    compdef _fx fx
fi
"""

FLAGS_FOR_COMPLETION = ["--help", "--raw", "--slurp", "--themes", "--version", "--yaml", "--toml", "--strict", "--no-inline"]

class _Undefined:
    pass
UNDEFINED = _Undefined()

class FxError(Exception):
    pass

class JSTypeError(FxError):
    pass

class JSVal:
    __slots__ = ("v",)

    def __init__(self, v=UNDEFINED):
        if isinstance(v, JSVal):
            v = v.v
        self.v = v

    @staticmethod
    def wrap(v):
        if isinstance(v, JSVal):
            return v
        if v is UNDEFINED:
            return JSVal(UNDEFINED)
        if isinstance(v, dict):
            return JSVal(OrderedDict((str(k), JSVal.wrap(val)) for k, val in v.items()))
        if isinstance(v, list) or isinstance(v, tuple):
            return JSVal([JSVal.wrap(x) for x in v])
        return JSVal(v)

    def is_undefined(self):
        return self.v is UNDEFINED

    def is_null(self):
        return self.v is None

    def unwrap(self, nested=True):
        if self.v is UNDEFINED:
            return None if nested else UNDEFINED
        if isinstance(self.v, OrderedDict) or isinstance(self.v, dict):
            return OrderedDict((k, JSVal.wrap(v).unwrap(True)) for k, v in self.v.items())
        if isinstance(self.v, list):
            return [JSVal.wrap(x).unwrap(True) for x in self.v]
        return self.v

    def __repr__(self):
        if self.is_undefined():
            return "undefined"
        return f"JSVal({self.v!r})"

    def __str__(self):
        return js_to_string(self)

    def __bool__(self):
        return js_truthy(self)

    def __len__(self):
        if isinstance(self.v, (list, str)):
            return len(self.v)
        if isinstance(self.v, (dict, OrderedDict)):
            return len(self.v)
        return 0

    def __iter__(self):
        if isinstance(self.v, list):
            return iter(self.v)
        raise TypeError("not iterable")

    def __getattr__(self, name):
        if name.startswith("__"):
            raise AttributeError(name)
        if self.v is UNDEFINED or self.v is None:
            raise JSTypeError(f"Cannot read property '{name}' of undefined")
        if isinstance(self.v, (dict, OrderedDict)):
            if name in self.v:
                return JSVal.wrap(self.v[name])
            if name == "toString":
                return lambda: JSVal("[object Object]")
            if name == "hasOwnProperty":
                return lambda key: JSVal(str(JSVal.wrap(key).v) in self.v)
            return JSVal(UNDEFINED)
        if isinstance(self.v, list):
            if name == "length":
                return JSVal(len(self.v))
            methods = {
                "map": self._arr_map,
                "filter": self._arr_filter,
                "reduce": self._arr_reduce,
                "find": self._arr_find,
                "findIndex": self._arr_find_index,
                "flatMap": self._arr_flat_map,
                "flat": self._arr_flat,
                "at": self._arr_at,
                "slice": self._arr_slice,
                "join": self._arr_join,
                "includes": self._arr_includes,
                "indexOf": self._arr_index_of,
                "sort": self._arr_sort,
                "reverse": self._arr_reverse,
                "toString": lambda: JSVal(js_to_string(self)),
                "push": self._arr_push,
                "pop": self._arr_pop,
            }
            if name in methods:
                return methods[name]
            return JSVal(UNDEFINED)
        if isinstance(self.v, str):
            if name == "length":
                return JSVal(len(self.v))
            methods = {
                "split": self._str_split,
                "trim": lambda: JSVal(self.v.strip()),
                "trimStart": lambda: JSVal(self.v.lstrip()),
                "trimEnd": lambda: JSVal(self.v.rstrip()),
                "toUpperCase": lambda: JSVal(self.v.upper()),
                "toLowerCase": lambda: JSVal(self.v.lower()),
                "startsWith": lambda s: JSVal(self.v.startswith(js_to_string(s))),
                "endsWith": lambda s: JSVal(self.v.endswith(js_to_string(s))),
                "includes": lambda s: JSVal(js_to_string(s) in self.v),
                "indexOf": lambda s: JSVal(self.v.find(js_to_string(s))),
                "slice": self._str_slice,
                "substring": self._str_substring,
                "replace": self._str_replace,
                "toString": lambda: JSVal(self.v),
            }
            if name in methods:
                return methods[name]
            return JSVal(UNDEFINED)
        # JavaScript boxes primitive numbers/booleans; most unknown members become undefined.
        if name == "toString":
            return lambda: JSVal(js_to_string(self))
        return JSVal(UNDEFINED)

    def __getitem__(self, key):
        keyv = JSVal.wrap(key).v if isinstance(key, JSVal) else key
        if self.v is UNDEFINED or self.v is None:
            raise JSTypeError(f"Cannot read property '{keyv}' of undefined")
        if isinstance(self.v, list):
            try:
                if isinstance(keyv, str) and re.fullmatch(r"-?\d+", keyv):
                    keyv = int(keyv)
                if isinstance(keyv, (int, float)) and int(keyv) == keyv:
                    i = int(keyv)
                    if 0 <= i < len(self.v):
                        return JSVal.wrap(self.v[i])
                    return JSVal(UNDEFINED)
            except Exception:
                pass
            if keyv == "length":
                return JSVal(len(self.v))
            return JSVal(UNDEFINED)
        if isinstance(self.v, (dict, OrderedDict)):
            return JSVal.wrap(self.v.get(str(keyv), UNDEFINED))
        if isinstance(self.v, str):
            if keyv == "length":
                return JSVal(len(self.v))
            try:
                if isinstance(keyv, str) and re.fullmatch(r"-?\d+", keyv):
                    keyv = int(keyv)
                if isinstance(keyv, (int, float)) and int(keyv) == keyv:
                    i = int(keyv)
                    if 0 <= i < len(self.v):
                        return JSVal(self.v[i])
            except Exception:
                pass
            return JSVal(UNDEFINED)
        return JSVal(UNDEFINED)

    def __setitem__(self, key, value):
        if isinstance(self.v, list):
            i = int(JSVal.wrap(key).v)
            while len(self.v) <= i:
                self.v.append(JSVal(UNDEFINED))
            self.v[i] = JSVal.wrap(value)
        elif isinstance(self.v, (dict, OrderedDict)):
            self.v[str(JSVal.wrap(key).v)] = JSVal.wrap(value)

    def _arr_map(self, fn):
        return JSVal([JSVal.wrap(call_fn(fn, JSVal.wrap(v), JSVal(i), self)) for i, v in enumerate(self.v)])

    def _arr_filter(self, fn):
        out = []
        for i, v in enumerate(self.v):
            if js_truthy(call_fn(fn, JSVal.wrap(v), JSVal(i), self)):
                out.append(JSVal.wrap(v))
        return JSVal(out)

    def _arr_reduce(self, fn, init=UNDEFINED):
        vals = list(self.v)
        if init is UNDEFINED:
            if not vals:
                raise JSTypeError("Reduce of empty array with no initial value")
            acc = JSVal.wrap(vals.pop(0))
            start_index = 1
        else:
            acc = JSVal.wrap(init)
            start_index = 0
        for offset, v in enumerate(vals):
            acc = JSVal.wrap(call_fn(fn, acc, JSVal.wrap(v), JSVal(start_index + offset), self))
        return acc

    def _arr_find(self, fn):
        for i, v in enumerate(self.v):
            if js_truthy(call_fn(fn, JSVal.wrap(v), JSVal(i), self)):
                return JSVal.wrap(v)
        return JSVal(UNDEFINED)

    def _arr_find_index(self, fn):
        for i, v in enumerate(self.v):
            if js_truthy(call_fn(fn, JSVal.wrap(v), JSVal(i), self)):
                return JSVal(i)
        return JSVal(-1)

    def _arr_flat_map(self, fn):
        out = []
        for i, v in enumerate(self.v):
            r = JSVal.wrap(call_fn(fn, JSVal.wrap(v), JSVal(i), self))
            if isinstance(r.v, list):
                out.extend(r.v)
            else:
                out.append(r)
        return JSVal(out)

    def _arr_flat(self, depth=1):
        d = int(js_to_number(depth)) if not JSVal.wrap(depth).is_undefined() else 1
        def flat(vals, depth):
            out = []
            for item in vals:
                item = JSVal.wrap(item)
                if depth > 0 and isinstance(item.v, list):
                    out.extend(flat(item.v, depth-1))
                else:
                    out.append(item)
            return out
        return JSVal(flat(self.v, d))

    def _arr_at(self, idx):
        i = int(js_to_number(idx))
        if i < 0:
            i += len(self.v)
        if 0 <= i < len(self.v):
            return JSVal.wrap(self.v[i])
        return JSVal(UNDEFINED)

    def _arr_slice(self, start=0, end=UNDEFINED):
        n = len(self.v)
        s = int(js_to_number(start)) if start is not UNDEFINED else 0
        e = n if end is UNDEFINED or JSVal.wrap(end).is_undefined() else int(js_to_number(end))
        if s < 0: s = max(n + s, 0)
        if e < 0: e = max(n + e, 0)
        return JSVal(self.v[s:e])

    def _arr_join(self, sep=","):
        if JSVal.wrap(sep).is_undefined():
            sep = ","
        else:
            sep = js_to_string(sep)
        return JSVal(sep.join("" if JSVal.wrap(x).is_undefined() or JSVal.wrap(x).is_null() else js_to_string(x) for x in self.v))

    def _arr_includes(self, item):
        item = JSVal.wrap(item)
        return JSVal(any(js_equal(JSVal.wrap(v), item) for v in self.v))

    def _arr_index_of(self, item):
        item = JSVal.wrap(item)
        for i, v in enumerate(self.v):
            if js_equal(JSVal.wrap(v), item):
                return JSVal(i)
        return JSVal(-1)

    def _arr_sort(self, fn=UNDEFINED):
        vals = list(self.v)
        if fn is UNDEFINED or JSVal.wrap(fn).is_undefined():
            vals.sort(key=lambda a: js_to_string(a))
        else:
            # Small insertion sort with JS comparator.
            for i in range(1, len(vals)):
                j = i
                while j > 0 and js_to_number(call_fn(fn, JSVal.wrap(vals[j-1]), JSVal.wrap(vals[j]))) > 0:
                    vals[j-1], vals[j] = vals[j], vals[j-1]
                    j -= 1
        return JSVal(vals)

    def _arr_reverse(self):
        return JSVal(list(reversed(self.v)))

    def _arr_push(self, *items):
        self.v.extend(JSVal.wrap(i) for i in items)
        return JSVal(len(self.v))

    def _arr_pop(self):
        if self.v:
            return JSVal.wrap(self.v.pop())
        return JSVal(UNDEFINED)

    def _str_split(self, sep=UNDEFINED):
        if sep is UNDEFINED or JSVal.wrap(sep).is_undefined():
            return JSVal([self.v])
        sep = js_to_string(sep)
        if sep == "":
            return JSVal(list(self.v))
        return JSVal(self.v.split(sep))

    def _str_slice(self, start=0, end=UNDEFINED):
        n = len(self.v)
        s = int(js_to_number(start)) if start is not UNDEFINED else 0
        e = n if end is UNDEFINED or JSVal.wrap(end).is_undefined() else int(js_to_number(end))
        if s < 0: s = max(n + s, 0)
        if e < 0: e = max(n + e, 0)
        return JSVal(self.v[s:e])

    def _str_substring(self, start=0, end=UNDEFINED):
        n = len(self.v)
        s = max(0, int(js_to_number(start)))
        e = n if end is UNDEFINED or JSVal.wrap(end).is_undefined() else max(0, int(js_to_number(end)))
        if s > e: s, e = e, s
        return JSVal(self.v[s:e])

    def _str_replace(self, old, new):
        return JSVal(self.v.replace(js_to_string(old), js_to_string(new), 1))

    # Arithmetic and comparisons.
    def __add__(self, other):
        return JSVal(js_add(self, other))
    def __radd__(self, other):
        return JSVal(js_add(other, self))
    def __sub__(self, other):
        return JSVal(js_num_bin(self, other, lambda a,b: a-b))
    def __rsub__(self, other):
        return JSVal(js_num_bin(other, self, lambda a,b: a-b))
    def __mul__(self, other):
        return JSVal(js_num_bin(self, other, lambda a,b: a*b))
    def __rmul__(self, other):
        return JSVal(js_num_bin(other, self, lambda a,b: a*b))
    def __truediv__(self, other):
        def div(a,b):
            if b == 0:
                if a == 0 or math.isnan(a): return math.nan
                return math.copysign(math.inf, a)
            return a/b
        return JSVal(js_num_bin(self, other, div))
    def __rtruediv__(self, other):
        return JSVal(JSVal.wrap(other).__truediv__(self).v)
    def __mod__(self, other):
        def mod(a,b):
            if b == 0: return math.nan
            return math.fmod(a,b)
        return JSVal(js_num_bin(self, other, mod))
    def __rmod__(self, other):
        return JSVal(js_num_bin(other, self, lambda a,b: math.nan if b == 0 else math.fmod(a,b)))
    def __neg__(self):
        return JSVal(-js_to_number(self))
    def __pos__(self):
        return JSVal(js_to_number(self))
    def __eq__(self, other):
        return js_equal(self, other)
    def __ne__(self, other):
        return not js_equal(self, other)
    def __lt__(self, other):
        return js_compare(self, other) < 0
    def __le__(self, other):
        return js_compare(self, other) <= 0
    def __gt__(self, other):
        return js_compare(self, other) > 0
    def __ge__(self, other):
        return js_compare(self, other) >= 0


def js_to_number(v):
    v = JSVal.wrap(v)
    if v.v is UNDEFINED:
        return math.nan
    if v.v is None:
        return 0.0
    if isinstance(v.v, bool):
        return 1.0 if v.v else 0.0
    if isinstance(v.v, (int, float)):
        return float(v.v)
    if isinstance(v.v, str):
        s = v.v.strip()
        if s == "": return 0.0
        try:
            return float(s)
        except Exception:
            return math.nan
    if isinstance(v.v, list):
        return js_to_number(js_to_string(v))
    return math.nan


def js_num_str(n):
    if isinstance(n, JSVal): n = n.v
    if isinstance(n, bool): return "true" if n else "false"
    if isinstance(n, int): return str(n)
    if isinstance(n, float):
        if math.isnan(n): return "NaN"
        if math.isinf(n): return "Infinity" if n > 0 else "-Infinity"
        if n == int(n): return str(int(n))
        return ("%s" % n)
    return str(n)


def js_to_string(v):
    v = JSVal.wrap(v)
    if v.v is UNDEFINED: return "undefined"
    if v.v is None: return "null"
    if isinstance(v.v, bool): return "true" if v.v else "false"
    if isinstance(v.v, (int, float)): return js_num_str(v.v)
    if isinstance(v.v, str): return v.v
    if isinstance(v.v, list):
        parts = []
        for x in v.v:
            x = JSVal.wrap(x)
            if x.is_undefined() or x.is_null():
                parts.append("")
            else:
                parts.append(js_to_string(x))
        return ",".join(parts)
    if isinstance(v.v, (dict, OrderedDict)):
        return "[object Object]"
    return str(v.v)


def js_truthy(v):
    v = JSVal.wrap(v)
    if v.v is UNDEFINED or v.v is None: return False
    if isinstance(v.v, bool): return v.v
    if isinstance(v.v, (int, float)):
        return not (v.v == 0 or (isinstance(v.v, float) and math.isnan(v.v)))
    if isinstance(v.v, str): return len(v.v) > 0
    return True


def js_add(a, b):
    av, bv = JSVal.wrap(a), JSVal.wrap(b)
    if isinstance(av.v, (str, list, dict, OrderedDict)) or isinstance(bv.v, (str, list, dict, OrderedDict)):
        return js_to_string(av) + js_to_string(bv)
    an, bn = js_to_number(av), js_to_number(bv)
    return an + bn


def js_num_bin(a, b, op):
    an, bn = js_to_number(a), js_to_number(b)
    try:
        return op(an, bn)
    except Exception:
        return math.nan


def _plain(v):
    return JSVal.wrap(v).unwrap(True)


def js_equal(a, b):
    a, b = JSVal.wrap(a), JSVal.wrap(b)
    if (a.is_undefined() and b.is_null()) or (a.is_null() and b.is_undefined()):
        return True
    if a.is_undefined() and b.is_undefined(): return True
    av, bv = a.v, b.v
    if isinstance(av, (int, float, bool)) or isinstance(bv, (int, float, bool)):
        an, bn = js_to_number(a), js_to_number(b)
        if math.isnan(an) or math.isnan(bn): return False
        return an == bn
    return _plain(a) == _plain(b)


def js_compare(a, b):
    a, b = JSVal.wrap(a), JSVal.wrap(b)
    if isinstance(a.v, str) and isinstance(b.v, str):
        return (a.v > b.v) - (a.v < b.v)
    an, bn = js_to_number(a), js_to_number(b)
    if math.isnan(an) or math.isnan(bn): return 1
    return (an > bn) - (an < bn)


def call_fn(fn, *args):
    # JS callbacks ignore extra arguments.  Python lambdas do not, so try decreasing arity.
    if isinstance(fn, JSVal):
        fn = fn.v
    if not callable(fn):
        raise JSTypeError("Value is not a function")
    last = None
    for n in range(len(args), -1, -1):
        try:
            return fn(*args[:n])
        except TypeError as e:
            last = e
            continue
    if last:
        raise last
    return fn()

class JSONObject:
    @staticmethod
    def keys(x):
        x = JSVal.wrap(x)
        if isinstance(x.v, (dict, OrderedDict)):
            return JSVal(list(x.v.keys()))
        if isinstance(x.v, list):
            return JSVal([str(i) for i in range(len(x.v))])
        return JSVal([])
    @staticmethod
    def values(x):
        x = JSVal.wrap(x)
        if isinstance(x.v, (dict, OrderedDict)):
            return JSVal(list(x.v.values()))
        if isinstance(x.v, list):
            return JSVal(list(x.v))
        return JSVal([])
    @staticmethod
    def entries(x):
        x = JSVal.wrap(x)
        if isinstance(x.v, (dict, OrderedDict)):
            return JSVal([[k, v] for k, v in x.v.items()])
        if isinstance(x.v, list):
            return JSVal([[str(i), v] for i, v in enumerate(x.v)])
        return JSVal([])
    @staticmethod
    def fromEntries(entries):
        out = OrderedDict()
        for e in JSVal.wrap(entries).v if isinstance(JSVal.wrap(entries).v, list) else []:
            e = JSVal.wrap(e)
            if isinstance(e.v, list) and len(e.v) >= 2:
                out[js_to_string(e.v[0])] = JSVal.wrap(e.v[1])
        return JSVal(out)
    @staticmethod
    def assign(target, *sources):
        t = JSVal.wrap(target)
        if not isinstance(t.v, (dict, OrderedDict)):
            t = JSVal(OrderedDict())
        for src in sources:
            s = JSVal.wrap(src)
            if isinstance(s.v, (dict, OrderedDict)):
                for k, v in s.v.items():
                    t.v[k] = JSVal.wrap(v)
        return t

class JSONClass:
    @staticmethod
    def stringify(x):
        x = JSVal.wrap(x).unwrap(True)
        return JSVal(json.dumps(x, ensure_ascii=False, separators=(",", ":"), allow_nan=True))
    @staticmethod
    def parse(s):
        return JSVal.wrap(json.loads(js_to_string(s), object_pairs_hook=OrderedDict))

class MathClass:
    @staticmethod
    def max(*args):
        if not args: return JSVal(-math.inf)
        return JSVal(max(js_to_number(a) for a in args))
    @staticmethod
    def min(*args):
        if not args: return JSVal(math.inf)
        return JSVal(min(js_to_number(a) for a in args))
    @staticmethod
    def abs(x): return JSVal(abs(js_to_number(x)))
    @staticmethod
    def round(x): return JSVal(round(js_to_number(x)))
    @staticmethod
    def floor(x): return JSVal(math.floor(js_to_number(x)))
    @staticmethod
    def ceil(x): return JSVal(math.ceil(js_to_number(x)))
    @staticmethod
    def trunc(x): return JSVal(math.trunc(js_to_number(x)))


def Number(x=0):
    return JSVal(js_to_number(x))
def String(x=""):
    return JSVal(js_to_string(x))
def Boolean(x=False):
    return JSVal(js_truthy(x))
def parseInt(x, base=10):
    s = js_to_string(x).strip()
    m = re.match(r"^[+-]?[0-9a-zA-Z]+", s)
    if not m: return JSVal(math.nan)
    try: return JSVal(int(m.group(0), int(js_to_number(base))))
    except Exception: return JSVal(math.nan)
def parseFloat(x):
    m = re.match(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?", js_to_string(x).strip())
    return JSVal(float(m.group(0))) if m else JSVal(math.nan)
def BigInt(x): return JSVal(int(js_to_number(x)))
def Symbol(x=""): return JSVal(js_to_string(x))
def Date(*args):
    if not args:
        return JSVal(time.strftime("%Y-%m-%d %H:%M:%S +0000 UTC", time.gmtime()))
    n = js_to_number(args[0]) / 1000.0
    return JSVal(time.strftime("%Y-%m-%d %H:%M:%S +0000 UTC", time.gmtime(n)))

# ---------- expression translation ----------

def replace_word(s, word, repl):
    return re.sub(r"(?<![\w$])" + re.escape(word) + r"(?![\w$])", repl, s)


def find_top_level_arrow(s):
    in_str = None; esc = False; depth = 0
    i = 0
    while i < len(s)-1:
        c = s[i]
        if in_str:
            if esc: esc = False
            elif c == "\\": esc = True
            elif c == in_str: in_str = None
            i += 1; continue
        if c in "'\"`":
            in_str = c; i += 1; continue
        if c in "([{": depth += 1
        elif c in ")]}": depth -= 1
        elif c == "=" and s[i+1] == ">":
            return i
        i += 1
    return -1


def matching_left_paren(s, pos):
    depth = 0
    for i in range(pos, -1, -1):
        if s[i] == ')': depth += 1
        elif s[i] == '(':
            depth -= 1
            if depth == 0:
                return i
    return -1


def scan_arrow_body(s, start):
    in_str = None; esc = False; depth = 0
    i = start
    while i < len(s):
        c = s[i]
        if in_str:
            if esc: esc = False
            elif c == "\\": esc = True
            elif c == in_str: in_str = None
            i += 1; continue
        if c in "'\"`": in_str = c; i += 1; continue
        if c in "([{": depth += 1
        elif c in ")]}":
            if depth == 0:
                break
            depth -= 1
        elif c == ',' and depth == 0:
            break
        i += 1
    return i


def translate_arrows(s):
    # Repeatedly replace the left-most arrow expression. Handles common callback forms.
    while True:
        idx = find_top_level_arrow(s)
        if idx < 0:
            break
        # find left side
        j = idx - 1
        while j >= 0 and s[j].isspace(): j -= 1
        if j >= 0 and s[j] == ')':
            l = matching_left_paren(s, j)
            params = s[l+1:j].strip()
            left_start = l
        else:
            k = j
            while k >= 0 and re.match(r"[\w$]", s[k]): k -= 1
            params = s[k+1:j+1].strip()
            left_start = k+1
        body_start = idx + 2
        while body_start < len(s) and s[body_start].isspace(): body_start += 1
        body_end = scan_arrow_body(s, body_start)
        body = s[body_start:body_end].strip()
        if params == "":
            pyparams = ""
        else:
            pyparams = ",".join(p.strip().replace('$','_') for p in params.split(',') if p.strip())
        body_py = translate_expr(body, nested=True)
        repl = f"(lambda {pyparams}: {body_py})" if pyparams else f"(lambda: {body_py})"
        s = s[:left_start] + repl + s[body_end:]
    return s


def split_top_level(s, sep=','):
    parts=[]; start=0; depth=0; in_str=None; esc=False
    for i,c in enumerate(s):
        if in_str:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==in_str: in_str=None
            continue
        if c in "'\"`": in_str=c; continue
        if c in "([{": depth += 1
        elif c in ")]}": depth -= 1
        elif c == sep and depth == 0:
            parts.append(s[start:i]); start=i+1
    parts.append(s[start:])
    return parts


def find_top_level_colon(s):
    depth=0; in_str=None; esc=False
    for i,c in enumerate(s):
        if in_str:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==in_str: in_str=None
            continue
        if c in "'\"`": in_str=c; continue
        if c in "([{": depth += 1
        elif c in ")]}": depth -= 1
        elif c == ':' and depth == 0:
            return i
    return -1


def convert_object_literals(s):
    # Convert unquoted JS object keys in {a: 1} to Python dict keys. Conservative but useful.
    out=[]; i=0; in_str=None; esc=False
    while i < len(s):
        c=s[i]
        if in_str:
            out.append(c)
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==in_str: in_str=None
            i+=1; continue
        if c in "'\"`":
            in_str=c; out.append(c); i+=1; continue
        if c == '{':
            depth=1; j=i+1; in2=None; esc2=False
            while j < len(s) and depth>0:
                d=s[j]
                if in2:
                    if esc2: esc2=False
                    elif d=='\\': esc2=True
                    elif d==in2: in2=None
                else:
                    if d in "'\"`": in2=d
                    elif d=='{': depth+=1
                    elif d=='}': depth-=1
                j+=1
            if depth==0:
                inner=s[i+1:j-1]
                parts=split_top_level(inner)
                if parts and any(find_top_level_colon(p) >= 0 for p in parts if p.strip()):
                    newparts=[]
                    ok=True
                    for p in parts:
                        if not p.strip(): continue
                        ci=find_top_level_colon(p)
                        if ci < 0: ok=False; break
                        key=p[:ci].strip(); val=p[ci+1:].strip()
                        if (len(key)>=2 and key[0] in "'\"" and key[-1]==key[0]):
                            k=key
                        elif re.fullmatch(r"[A-Za-z_$][\w$]*", key):
                            k=repr(key)
                        else:
                            k=repr(key)
                        newparts.append(f"{k}: {convert_object_literals(val)}")
                    if ok:
                        out.append("{" + ", ".join(newparts) + "}")
                        i=j; continue
        out.append(c); i+=1
    return ''.join(out)


def translate_ternary(s):
    # One simple top-level JS conditional expression: cond ? a : b
    depth=0; in_str=None; esc=False; q=-1; colon=-1
    for i,c in enumerate(s):
        if in_str:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==in_str: in_str=None
            continue
        if c in "'\"`": in_str=c; continue
        if c in "([{": depth += 1
        elif c in ")]}": depth -= 1
        elif c == '?' and depth == 0:
            q=i
        elif c == ':' and depth == 0 and q >= 0:
            colon=i; break
    if q >= 0 and colon > q:
        cond=s[:q].strip(); a=s[q+1:colon].strip(); b=s[colon+1:].strip()
        return f"({translate_expr(a, nested=True)} if {translate_expr(cond, nested=True)} else {translate_expr(b, nested=True)})"
    return s


def transform_selector(expr, var='x'):
    # Implements fx's convenient .[] flatMap selector for common dot-only paths.
    # Returns None if no special [] selector is present.
    if not expr.startswith('.'):
        return None
    # Reject spaces before the selector to mimic parser strictness.
    def parse_from(rest, basevar):
        path = basevar
        i = 0
        saw_bracket = False
        # .[] at beginning
        if rest.startswith('.[]'):
            after = rest[3:]
            body = parse_body(after, 'x')
            return f"{path}.flatMap(lambda x: {body})"
        while i < len(rest):
            if rest[i] == '.':
                j = i+1
                if j < len(rest) and rest[j] == '[' and j+1 < len(rest) and rest[j+1] == ']':
                    after = rest[j+2:]
                    body = parse_body(after, 'x')
                    return f"{path}.flatMap(lambda x: {body})"
                m = re.match(r"[A-Za-z_$][\w$]*", rest[j:])
                if not m:
                    break
                name = m.group(0).replace('$','_')
                path += "." + name
                i = j + len(m.group(0))
                if rest[i:i+2] == '[]' and not saw_bracket:
                    after = rest[i+2:]
                    body = parse_body(after, 'x')
                    return f"{path}.flatMap(lambda x: {body})"
                continue
            elif rest[i] == '[':
                # ordinary index; after this fx does not rewrite following [] in observed cases
                depth=1; j=i+1; in_str=None; esc=False
                while j < len(rest) and depth>0:
                    c=rest[j]
                    if in_str:
                        if esc: esc=False
                        elif c=='\\': esc=True
                        elif c==in_str: in_str=None
                    else:
                        if c in "'\"`": in_str=c
                        elif c=='[': depth+=1
                        elif c==']': depth-=1
                    j+=1
                path += rest[i:j]
                saw_bracket = True
                i = j
                continue
            else:
                break
        return None
    def parse_body(after, elemvar):
        if after == '':
            return elemvar
        if after.startswith('.'):
            sub = parse_from(after, elemvar)
            if sub is not None:
                return sub
            return elemvar + after
        if after.startswith('['):
            return elemvar + after
        # operator or rest of JS expression, e.g. " + 1"
        return elemvar + after
    return parse_from(expr, var)


def translate_expr(expr, nested=False):
    s = expr
    if not nested:
        sel = transform_selector(s, 'x')
        if sel is not None:
            s = sel
        elif s.startswith('.'):
            s = 'x' + s
    else:
        if s.startswith('.'):
            s = 'x' + s
    # JS spellings and operators.
    s = s.replace('`', '"')
    s = re.sub(r"\bnew\s+Date\s*\(", "Date(", s)
    s = replace_word(s, 'this', 'x')
    s = replace_word(s, 'true', 'True')
    s = replace_word(s, 'false', 'False')
    s = replace_word(s, 'null', 'None')
    s = replace_word(s, 'undefined', 'UNDEFINED')
    s = replace_word(s, 'NaN', 'NAN')
    s = replace_word(s, 'Infinity', 'INF')
    s = s.replace('===', '==').replace('!==', '!=')
    s = s.replace('&&', ' and ').replace('||', ' or ')
    # Replace ! but leave != alone.
    s = re.sub(r"!(?!=)", " not ", s)
    s = translate_arrows(s)
    s = translate_ternary(s)
    s = convert_object_literals(s)
    # JavaScript permits $ in identifiers; Python does not. Keep common built-ins intact.
    s = re.sub(r"\$", "_", s)
    return s


def eval_filter(expr, value):
    py = translate_expr(expr)
    env = {
        'x': JSVal.wrap(value), 'JSVal': JSVal, 'UNDEFINED': UNDEFINED,
        'True': True, 'False': False, 'None': None, 'NAN': math.nan, 'INF': math.inf,
        'Object': JSONObject, 'JSON': JSONClass, 'Math': MathClass,
        'Number': Number, 'String': String, 'Boolean': Boolean,
        'parseInt': parseInt, 'parseFloat': parseFloat, 'BigInt': BigInt,
        'Symbol': Symbol, 'Date': Date,
        'len': len, 'sum': sum, 'min': min, 'max': max,
    }
    try:
        code = compile(py, '<fx>', 'eval')
    except Exception as e:
        raise SyntaxFxError(expr, py, str(e))
    try:
        res = eval(code, {'__builtins__': {}}, env)
        if callable(res):
            res = call_fn(res, JSVal.wrap(value))
        return JSVal.wrap(res)
    except FxError:
        raise
    except NameError as e:
        name = str(e).split("'")[1] if "'" in str(e) else str(e)
        raise FxRuntimeError(expr, py, f"ReferenceError: {name} is not defined")
    except Exception as e:
        raise FxRuntimeError(expr, py, type(e).__name__ + ": " + str(e))

class SyntaxFxError(FxError):
    def __init__(self, expr, py, msg):
        self.expr=expr; self.py=py; self.msg=msg
class FxRuntimeError(FxError):
    def __init__(self, expr, py, msg):
        self.expr=expr; self.py=py; self.msg=msg

# ---------- input parsing ----------

def strip_json_lenient(s, strict=False):
    out=[]; i=0; in_str=None; esc=False
    while i < len(s):
        c=s[i]
        if in_str:
            out.append(c)
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==in_str: in_str=None
            i+=1; continue
        if c in '"':
            in_str=c; out.append(c); i+=1; continue
        if c=='/' and i+1 < len(s) and s[i+1] in '/*':
            if strict:
                line=s.count('\n',0,i)+1
                raise ValueError(f"Comments are not allowed in strict mode on line {line}.")
            if s[i+1]=='/':
                i += 2
                while i < len(s) and s[i] != '\n': i += 1
                if i < len(s): out.append('\n'); i += 1
            else:
                i += 2
                while i+1 < len(s) and not (s[i]=='*' and s[i+1]=='/'):
                    if s[i]=='\n': out.append('\n')
                    i += 1
                i += 2
            continue
        out.append(c); i+=1
    s=''.join(out)
    # trailing commas
    out=[]; i=0; in_str=None; esc=False
    while i < len(s):
        c=s[i]
        if in_str:
            out.append(c)
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==in_str: in_str=None
            i+=1; continue
        if c=='"':
            in_str=c; out.append(c); i+=1; continue
        if c==',':
            j=i+1
            while j < len(s) and s[j].isspace(): j += 1
            if j < len(s) and s[j] in '}]':
                if strict:
                    line=s.count('\n',0,i)+1
                    raise ValueError(f"Trailing comma is not allowed in strict mode on line {line}.")
                i += 1; continue
        out.append(c); i+=1
    return ''.join(out)


def parse_json_stream(data, strict=False):
    if data == "": return []
    try:
        data2 = strip_json_lenient(data, strict)
    except ValueError as e:
        raise ParseInputError(str(e))
    dec = json.JSONDecoder(object_pairs_hook=OrderedDict)
    vals=[]; idx=0; n=len(data2)
    while True:
        while idx<n and data2[idx].isspace(): idx += 1
        if idx>=n: break
        try:
            val, end = dec.raw_decode(data2, idx)
            vals.append(JSVal.wrap(val))
            idx = end
        except json.JSONDecodeError as e:
            line = e.lineno
            raise ParseInputError(f"{e.msg} on line {line}.")
    return vals

class ParseInputError(Exception): pass

# A small YAML parser for the common JSON-like subset used by fx examples.
def parse_scalar_yaml(s):
    s=s.strip()
    if s == "" : return ""
    if s in ("null", "Null", "NULL", "~"): return None
    if s in ("true", "True", "TRUE"): return True
    if s in ("false", "False", "FALSE"): return False
    if (len(s)>=2 and s[0] in "'\"" and s[-1]==s[0]):
        try: return json.loads(s) if s[0]=='"' else s[1:-1]
        except Exception: return s[1:-1]
    if s.startswith('[') or s.startswith('{'):
        # Convert simple YAML inline collections to JSON-ish.
        try:
            js = re.sub(r"([{,]\s*)([A-Za-z_][\w-]*)(\s*:)", lambda m: m.group(1)+json.dumps(m.group(2))+m.group(3), s)
            return json.loads(js, object_pairs_hook=OrderedDict)
        except Exception:
            pass
    try:
        if re.fullmatch(r"[+-]?\d+", s): return int(s)
        if re.fullmatch(r"[+-]?(?:\d+\.\d*|\d*\.\d+)(?:[eE][+-]?\d+)?", s): return float(s)
    except Exception: pass
    return s


def parse_yaml_doc(text):
    raw_lines = text.splitlines()
    # strip blank/comment-only lines
    lines=[]
    for ln in raw_lines:
        if not ln.strip() or ln.lstrip().startswith('#'): continue
        lines.append((len(ln) - len(ln.lstrip(' ')), ln.strip()))
    if not lines: return None
    def parse_block(pos, indent):
        if pos >= len(lines): return None, pos
        # list block if first token is '- '
        if lines[pos][0] == indent and lines[pos][1].startswith('-'):
            arr=[]
            while pos < len(lines) and lines[pos][0] == indent and lines[pos][1].startswith('-'):
                item = lines[pos][1][1:].strip()
                pos += 1
                if item == "":
                    val, pos = parse_block(pos, indent+2)
                    arr.append(val)
                elif re.match(r"^[^:]+:\s*", item):
                    # inline mapping after dash
                    key, valtxt = item.split(':',1)
                    obj=OrderedDict()
                    if valtxt.strip(): obj[key.strip()] = parse_scalar_yaml(valtxt)
                    else:
                        val, pos = parse_block(pos, indent+2); obj[key.strip()] = val
                    # absorb following indented key-values
                    while pos < len(lines) and lines[pos][0] >= indent+2 and ':' in lines[pos][1] and not lines[pos][1].startswith('-'):
                        k, vt = lines[pos][1].split(':',1); pos += 1
                        if vt.strip(): obj[k.strip()] = parse_scalar_yaml(vt)
                        else:
                            val, pos = parse_block(pos, lines[pos-1][0]+2); obj[k.strip()] = val
                    arr.append(obj)
                else:
                    arr.append(parse_scalar_yaml(item))
            return arr, pos
        obj=OrderedDict()
        while pos < len(lines) and lines[pos][0] == indent and not lines[pos][1].startswith('-'):
            text = lines[pos][1]
            if ':' not in text: break
            key, valtxt = text.split(':',1)
            pos += 1
            if valtxt.strip():
                obj[key.strip()] = parse_scalar_yaml(valtxt)
            else:
                val, pos = parse_block(pos, indent+2)
                obj[key.strip()] = val
        return obj, pos
    val, _ = parse_block(0, lines[0][0])
    return val


def parse_yaml_stream(data):
    docs=[]; cur=[]
    for line in data.splitlines():
        if line.strip() == '---':
            if cur:
                docs.append('\n'.join(cur)); cur=[]
        elif line.strip() == '...':
            if cur:
                docs.append('\n'.join(cur)); cur=[]
        else:
            cur.append(line)
    if cur: docs.append('\n'.join(cur))
    if not docs and data.strip(): docs=[data]
    return [JSVal.wrap(parse_yaml_doc(d)) for d in docs if d.strip()]


def parse_toml_stream(data):
    # Python 3.11 has tomllib, but this environment may be 3.10.  Try it, then fallback.
    try:
        import tomllib
        return [JSVal.wrap(tomllib.loads(data))]
    except Exception:
        pass
    obj=OrderedDict(); cur=obj
    for line in data.splitlines():
        line=line.strip()
        if not line or line.startswith('#'): continue
        if line.startswith('[') and line.endswith(']'):
            names=[x.strip() for x in line[1:-1].split('.')]
            cur=obj
            for name in names:
                cur=cur.setdefault(name, OrderedDict())
            continue
        if '=' in line:
            k,v=line.split('=',1); k=k.strip(); v=v.strip()
            cur[k]=parse_toml_value(v)
    return [JSVal.wrap(obj)] if obj else []

def parse_toml_value(v):
    if '#' in v and not v.strip().startswith(('"', "'")):
        v=v.split('#',1)[0].strip()
    if v.startswith('[') and v.endswith(']'):
        inner=v[1:-1].strip()
        if not inner: return []
        return [parse_toml_value(p.strip()) for p in split_top_level(inner)]
    if (len(v)>=2 and v[0] in "'\"" and v[-1]==v[0]):
        try: return json.loads(v) if v[0]=='"' else v[1:-1]
        except Exception: return v[1:-1]
    if v in ('true','false'): return v=='true'
    try:
        if re.fullmatch(r"[+-]?\d+", v): return int(v)
        return float(v)
    except Exception:
        return v

# ---------- formatting ----------

def json_quote(s):
    return json.dumps(str(s), ensure_ascii=False)


def scalar_inline(v, quote_strings=True):
    v = JSVal.wrap(v)
    if v.v is UNDEFINED or v.v is None: return 'null'
    if isinstance(v.v, bool): return 'true' if v.v else 'false'
    if isinstance(v.v, (int, float)): return js_num_str(v.v)
    if isinstance(v.v, str): return json_quote(v.v) if quote_strings else v.v
    return json_quote(js_to_string(v))


def is_scalar(v):
    v = JSVal.wrap(v)
    return not isinstance(v.v, (list, dict, OrderedDict))


def can_inline(v, context, no_inline=False):
    if no_inline: return False
    v = JSVal.wrap(v)
    if is_scalar(v): return True
    if isinstance(v.v, list):
        if len(v.v) == 0: return True
        if len(v.v) == 1 and is_scalar(v.v[0]): return True
        if all(isinstance(JSVal.wrap(x).v, (int, float)) and not isinstance(JSVal.wrap(x).v, bool) for x in v.v):
            return True
        return False
    if isinstance(v.v, (dict, OrderedDict)):
        if len(v.v) == 0: return True
        if context == 'array' and all(is_scalar(val) for val in v.v.values()):
            return True
        return False
    return True


def inline_format(v, no_inline=False):
    v = JSVal.wrap(v)
    if is_scalar(v): return scalar_inline(v, True)
    if isinstance(v.v, list):
        if not v.v: return '[]'
        return '[ ' + ', '.join(inline_format(x, no_inline) for x in v.v) + ' ]'
    if isinstance(v.v, (dict, OrderedDict)):
        if not v.v: return '{}'
        return '{ ' + ', '.join(f'{json_quote(k)}: {inline_format(val, no_inline)}' for k,val in v.v.items()) + ' }'
    return scalar_inline(v, True)


def fmt_multiline(v, level=0, context='top', no_inline=False):
    v = JSVal.wrap(v)
    sp = '  ' * level
    if can_inline(v, context, no_inline):
        return inline_format(v, no_inline)
    if isinstance(v.v, (dict, OrderedDict)):
        if not v.v: return '{}'
        lines=[sp+'{']
        items=list(v.v.items())
        for idx,(k,val) in enumerate(items):
            comma=',' if idx < len(items)-1 else ''
            child=fmt_multiline(val, level+1, 'object', no_inline)
            cl=child.splitlines()
            prefix='  '*(level+1)+json_quote(k)+': '
            if len(cl)==1:
                lines.append(prefix+cl[0]+comma)
            else:
                lines.append(prefix+cl[0].lstrip())
                rest=cl[1:]
                if comma and rest: rest[-1] += comma
                lines.extend(rest)
        lines.append(sp+'}')
        return '\n'.join(lines)
    if isinstance(v.v, list):
        if not v.v: return '[]'
        lines=[sp+'[']
        for idx,val in enumerate(v.v):
            comma=',' if idx < len(v.v)-1 else ''
            child=fmt_multiline(val, level+1, 'array', no_inline)
            cl=child.splitlines()
            if len(cl)==1:
                lines.append('  '*(level+1)+cl[0]+comma)
            else:
                lines.append('  '*(level+1)+cl[0].lstrip())
                rest=cl[1:]
                if comma and rest: rest[-1] += comma
                lines.extend(rest)
        lines.append(sp+']')
        return '\n'.join(lines)
    return scalar_inline(v, True)


def render_output(v, no_inline=False):
    v = JSVal.wrap(v)
    if v.is_undefined():
        return None
    if isinstance(v.v, str):
        return v.v + '\n'
    if is_scalar(v):
        return scalar_inline(v, True) + '\n'
    return fmt_multiline(v, 0, 'top', no_inline) + '\n'

# ---------- flags/completion/themes ----------

def print_themes():
    sample = '{\n  "string": "Fox jumps over the lazy dog",\n  "number": 1234567890,\n  "boolean": true,\n  "null": null,\n  "collapsed": {"preview":…}\n}\n'
    themes = [str(i) for i in range(10)] + ['🔥', '🔵', '🟣', '🥝']
    for th in themes:
        sys.stdout.write(f'export FX_THEME="{th}"\n')
        sys.stdout.write(sample)
        sys.stderr.write('\n')


def completion_script(shell):
    if shell == 'bash': return 'complete -o filenames -C fx fx\n'
    if shell == 'zsh': return ZSH_COMP
    if shell == 'fish': return "complete --command fx --arguments '(COMP_FISH=(commandline -cp) fx)'\n"
    return 'unknown shell type\n'


def dynamic_completion(line, zsh=False):
    if not line:
        return
    parts = line.split(' ')
    cur = parts[-1]
    if line.endswith(' '): cur = ''
    outs=[]
    if cur == '--':
        if zsh:
            outs=[f"{f}\t{f}\tflag" for f in FLAGS_FOR_COMPLETION]
        else:
            outs=FLAGS_FOR_COMPLETION[:]
    elif cur == '' or '/' in cur:
        prefix = cur
        pattern = (prefix + '*') if prefix else '*'
        names = sorted(glob.glob(pattern))
        # Include dotfiles only for empty cwd completion, as observed.
        if prefix == '':
            names = sorted(glob.glob('.*') + glob.glob('*'))
            names = [n for n in names if os.path.basename(n) not in ('.','..')]
        for n in names:
            if zsh:
                disp = n + ('/' if os.path.isdir(n) else '')
                outs.append(f"{disp}\t{n}\tfile")
            else:
                outs.append(n)
    if outs:
        sys.stdout.write('\n'.join(outs))


def parse_args(argv):
    opts = {'raw':False,'slurp':False,'yaml':False,'toml':False,'strict':False,'no_inline':False,'game':False}
    filters=[]; i=0
    while i < len(argv):
        a=argv[i]
        if a in ('-h','--help'):
            opts['help']=True; i+=1; continue
        if a in ('-v','--version'):
            opts['version']=True; i+=1; continue
        if a == '--themes':
            opts['themes']=True; i+=1; continue
        if a == '--comp':
            if i+1 >= len(argv):
                sys.stderr.write('flag needs an argument: -comp\nUsage of ./executable:\n  -comp string\n    \t\n')
                sys.exit(2)
            opts['comp']=argv[i+1]; i+=2; continue
        if a in ('-r','--raw'):
            opts['raw']=True; i+=1; continue
        if a in ('-s','--slurp'):
            opts['slurp']=True; i+=1; continue
        if a in ('--yaml',):
            opts['yaml']=True; i+=1; continue
        if a in ('--toml',):
            opts['toml']=True; i+=1; continue
        if a == '--strict':
            opts['strict']=True; i+=1; continue
        if a == '--no-inline':
            opts['no_inline']=True; i+=1; continue
        if a == '--game-of-life':
            opts['game']=True; i+=1; continue
        # combined short flags -rs/-sr
        if a.startswith('-') and len(a)>2 and all(ch in 'rsvh' for ch in a[1:]):
            for ch in a[1:]:
                if ch=='r': opts['raw']=True
                elif ch=='s': opts['slurp']=True
                elif ch=='v': opts['version']=True
                elif ch=='h': opts['help']=True
            i+=1; continue
        filters.append(a); i+=1
    return opts, filters


def panic_no_tty():
    sys.stderr.write('panic: could not open a new TTY: open /dev/tty: no such device or address\n\n')
    sys.stderr.write('goroutine 1 [running]:\nmain.main()\n\t/workspace/main.go:317 +0x191e\n')
    sys.exit(2)


def run_game():
    # A lightweight facsimile: clear screen and animate until interrupted.
    sys.stdout.write('\x1b[2J\x1b[?25l')
    sys.stdout.flush()
    chars=[' ', '▄', '▀', '█']
    try:
        while True:
            sys.stdout.write('\x1b[H')
            for _ in range(24):
                sys.stdout.write(''.join(random.choice(chars) if random.random()<0.08 else ' ' for _ in range(80))+'\n')
            sys.stdout.flush(); time.sleep(0.08)
    except KeyboardInterrupt:
        sys.stdout.write('\x1b[?25h')


def read_inputs(opts, filters):
    data = sys.stdin.read()
    # If stdin is a TTY, fx normally treats existing leading args as filenames. Support that useful path.
    if data == '' and sys.stdin.isatty():
        file_args=[]; rest=[]; found_nonfile=False
        for f in filters:
            if not found_nonfile and os.path.exists(f) and os.path.isfile(f):
                file_args.append(f)
            else:
                found_nonfile=True; rest.append(f)
        if file_args:
            data=''.join(open(f, 'r', encoding='utf-8').read() for f in file_args)
            filters[:] = rest
    if opts['raw']:
        vals=[JSVal(line) for line in data.splitlines()]
        if data and not data.endswith(('\n','\r')) and vals == []:
            vals=[JSVal(data)]
        if opts['slurp']:
            return [JSVal(vals)]
        return vals
    if opts['yaml']:
        vals=parse_yaml_stream(data)
    elif opts['toml']:
        vals=parse_toml_stream(data)
    else:
        vals=parse_json_stream(data, opts['strict'])
    if opts['slurp']:
        return [JSVal(vals)]
    return vals


def print_fx_error(e):
    if isinstance(e, (SyntaxFxError, FxRuntimeError)):
        expr=e.expr
        sys.stderr.write(f"\n  {expr}\n  {'^'*max(1,len(expr))}\n\n")
        if getattr(e, 'py', None) and e.py != expr:
            sys.stderr.write(f"{e.py}\n\n")
        msg=e.msg
        if isinstance(e, SyntaxFxError):
            if 'invalid syntax' in msg:
                msg='Unexpected token } '
            elif 'unmatched' in msg or 'was never closed' in msg:
                msg='Unexpected token } '
        sys.stderr.write(msg + ('\n' if not msg.endswith('\n') else ''))
    else:
        sys.stderr.write(str(e) + '\n')


def main(argv):
    if 'COMP_FISH' in os.environ:
        dynamic_completion(os.environ.get('COMP_FISH',''), zsh=False)
        return 0
    if 'COMP_ZSH' in os.environ:
        dynamic_completion(os.environ.get('COMP_ZSH',''), zsh=True)
        return 0
    opts, filters = parse_args(argv)
    if opts.get('help'):
        sys.stdout.write(HELP_TEXT)
        return 0
    if opts.get('version'):
        sys.stdout.write(VERSION+'\n')
        return 0
    if opts.get('themes'):
        print_themes(); return 0
    if 'comp' in opts:
        sys.stdout.write(completion_script(opts['comp'])); return 0
    if opts.get('game'):
        run_game(); return 0

    # No processor expression means the original opens the TUI. In this headless
    # benchmark environment that path panics when /dev/tty is unavailable.
    if not filters:
        panic_no_tty()
    try:
        values = read_inputs(opts, filters)
    except ParseInputError as e:
        sys.stderr.write(str(e)+'\n')
        return 1
    except Exception as e:
        sys.stderr.write(str(e)+'\n')
        return 1

    # Parse filters even if there is no input, so syntax errors are still reported.
    for f in filters:
        try:
            compile(translate_expr(f), '<fx>', 'eval')
        except Exception as e:
            print_fx_error(SyntaxFxError(f, translate_expr(f), str(e)))
            return 1

    for val in values:
        cur = val
        try:
            for f in filters:
                cur = eval_filter(f, cur)
        except FxError as e:
            print_fx_error(e)
            return 1 if isinstance(e, SyntaxFxError) or isinstance(e, FxRuntimeError) else 1
        out = render_output(cur, opts['no_inline'])
        if out is None:
            sys.stderr.write('undefined\n')
        else:
            sys.stdout.write(out)
    return 0

if __name__ == '__main__':
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        try: sys.stdout.close()
        except Exception: pass
        sys.exit(0)
